-- Insert Quiz Questions for Lesson: Package a Clear Offer and Price

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 24 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 24 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm24-package-clear-offer-price' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m24-package-clear-offer-price not found in module 24';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the difference between a course and an offer?', 
    '["The course is free; the offer is paid","They are the same thing with different names","The course is the lesson content; the offer packages it for purchase or access","The offer contains more lessons than the course"]'::jsonb,
    'The course is the lesson content; the offer packages it for purchase or access',
    'The course is the lesson content and classroom. The offer packages it for purchase or access. One course can have multiple offers (free, paid, subscription).', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What status must a membership offer have before you share it for sale?', 
    '["Draft","Pending Review","Archived","Published"]'::jsonb,
    'Published',
    'The offer must be Published before sharing it for sale. Draft offers are not accessible to buyers. Always verify the status before sharing links.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do when choosing a checkout route?', 
    '["Let the customer choose their preferred route","Set up all three routes for maximum flexibility","Always use the most complex route available","Choose one working route and avoid mixing paths"]'::jsonb,
    'Choose one working route and avoid mixing paths',
    'Choose one working checkout route: Offers, Payment Product, or Direct Pricing. Mixing paths can create duplicate enrollments and confusion. Test one route thoroughly.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

