-- Insert Quiz Questions for Lesson: Verify Payments and Student Access

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 24 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 24 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm24-verify-payments-student-access' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m24-verify-payments-student-access not found in module 24';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you check immediately after an approved test purchase?', 
    '["Your bank account balance","That the correct learner has access to the correct course and can open Lesson 1","Social media engagement on the offer post","The number of website visitors"]'::jsonb,
    'That the correct learner has access to the correct course and can open Lesson 1',
    'After a test purchase, verify that the correct learner account has access to the correct course and can open Lesson 1. This confirms the entire buyer journey works end-to-end.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you not grant paid course access based on a form submission alone?', 
    '["Forms cannot capture email addresses","A form submission does not confirm successful payment","Payment providers reject form-based access","Forms are too slow to process"]'::jsonb,
    'A form submission does not confirm successful payment',
    'A form submission alone is not proof of payment. Someone could submit the form without paying. Only grant access after verified successful payment, using Course Grant Offer if needed.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you create a second grant workflow?', 
    '["For every course to be safe","Only if a separate external checkout or sales route genuinely requires one","For all paid courses automatically","When the first workflow fails"]'::jsonb,
    'Only if a separate external checkout or sales route genuinely requires one',
    'Do not create a second grant workflow unless genuinely required. Properly connected course-offer purchases grant access automatically. Extra workflows create complexity and potential conflicts.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

