    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'm24-welcome-customer-guide-lesson-1' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson m24-welcome-customer-guide-lesson-1 not found in module 24';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What five things should a welcome email tell the student?', 
    '["Module outline, lesson count, video duration, certificate details, community link","Instructor bio, company history, testimonials, refund policy, terms of service","Price, discount, expiry, bonus, guarantee","Course purchased, login steps, where to start, worksheet location, support contact"]'::jsonb,
    'Course purchased, login steps, where to start, worksheet location, support contact',
    'A welcome email should answer: What did I buy? How do I sign in? Where do I start? Where is the worksheet? Who do I contact for help? These five items remove friction and get learners started immediately.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What trigger should start the welcome workflow?', 
    '["Form Submitted","Product Access Granted with the correct product filter","Contact Created","Appointment Booked"]'::jsonb,
    'Product Access Granted with the correct product filter',
    'Use Product Access Granted with the correct product filter. This fires when the learner actually gets course access, not when they register, submit a form, or create an account.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you test actual behavior before adding a welcome email?', 
    '["Welcome emails always conflict with payment confirmations","Welcome emails are optional and rarely needed","Testing is only required for paid courses","Some enrollment methods already send standard notifications"]'::jsonb,
    'Some enrollment methods already send standard notifications',
    'Some enrollment methods send standard account or portal notifications automatically. Test actual behavior to avoid duplicate emails and ensure your welcome adds value rather than noise.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

